 "content": "def transform(grid):
    # Fill alternating gaps between same-colored markers horizontally.
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    fg = min((v for v in set(v for row in grid for v in row) if v != bg), default=0)
    fill = (fg + 1) % 10
    for r, row in enumerate(grid):
        positions = [c for c, v in enumerate(row) if v == fg]
        for a, b in zip(positions, positions[1:]):
            if b - a == 2 and row[a+1] == bg:
                out[r][a+1] = fill
    return out
