{
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    colors = set(v for row in grid for v in row)
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    fg = min((v for v in colors if v != bg), default=0)
    fill = 2 if fg == 1 else 0
    for ri, row in enumerate(grid):
        cols = [ci for ci, value in enumerate(row) if value == fg]
        for left, right in zip(cols, cols[1:]):
            if right - left == 2 and row[left + 1] == bg:
                out[ri][left + 1] = fill
    return out
